import React, { useEffect, useState } from "react";
import * as Curve from "@visx/curve";
import * as Shape from "@visx/shape";
import _ from "lodash";
import { useSpring, useTransition, animated } from "react-spring";

import "../assets/css/circles.css";

function HomeAnimation(props) {
  // In pixels
  let period = 100;
  let amplitude = 40;

  let width = 30 * Math.PI;
  let height = 100;

  const [step, setStep] = useState(0);

  const transitions = useTransition({ inputStep: 0, from: { inputStep: 100 } });

  useEffect(
    () => setInterval(() => setStep((currentStep) => currentStep + 1), 200),
    []
  );

  let calculateData = (value) => {
    console.log("called: ", value);
    let newData = [];

    _.times(width, (loop) => {
      let transformedStep = loop + value;
      let result = amplitude * Math.sin((Math.PI / period) * transformedStep);
      newData.push([loop, result + 50]);
    });

    return newData;
  };

  return transitions.map((value) => (
    <animated.svg width={width} height={height} key={value.key}>
      {console.log(value)}
      <Shape.LinePath
        curve={Curve.curveCatmullRom}
        data={calculateData(step)}
        stroke="black"
        strokeWidth={3}
      />
    </animated.svg>
  ));
}

export default HomeAnimation;
